<?php
require_once __DIR__.'/../lib/app.php';require_once __DIR__.'/../lib/notify.php';$pageTitle='신청·결재';include '_top.php';$pdo=db();$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];$action=$_POST['action'];$u=admin_user();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT lr.*,e.phone,e.name employee_name,e.position,e.department_id,e.alimtalk_opt_in FROM leave_requests lr JOIN employees e ON e.id=lr.employee_id WHERE lr.id=? FOR UPDATE');$s->execute([$id]);$r=$s->fetch();if(!$r)throw new Exception('신청을 찾을 수 없습니다.');if(!can_view_department((int)$r['department_id']))throw new Exception('해당 부서의 처리 권한이 없습니다.');$employeeId=admin_employee_id();$a=$pdo->prepare("SELECT * FROM request_approvals WHERE request_id=? AND approver_employee_id=? AND status='pending'");$a->execute([$id,$employeeId]);$ap=$a->fetch();if(!$ap&&!can_manage_hr())throw new Exception('현재 결재 차례가 아닙니다.');$comment=trim($_POST['comment']??'');if($action==='reject'){$pdo->prepare("UPDATE leave_requests SET status='rejected',reject_reason=? WHERE id=?")->execute([$comment,$id]);if($ap)$pdo->prepare("UPDATE request_approvals SET status='rejected',comment=?,acted_at=NOW() WHERE id=?")->execute([$comment,$ap['id']]);$event='rejected';}else{if($ap)$pdo->prepare("UPDATE request_approvals SET status='approved',comment=?,acted_at=NOW() WHERE id=?")->execute([$comment,$ap['id']]);$next=$pdo->prepare("SELECT * FROM request_approvals WHERE request_id=? AND status='waiting' ORDER BY step_order LIMIT 1");$next->execute([$id]);$n=$next->fetch();if($n){$pdo->prepare("UPDATE request_approvals SET status='pending' WHERE id=?")->execute([$n['id']]);$pdo->prepare("UPDATE leave_requests SET status='in_approval',current_step=? WHERE id=?")->execute([$n['step_order'],$id]);$event='next_approval';$nextApproval=$n;}else{$pdo->prepare("UPDATE leave_requests SET status='approved',approved_at=NOW() WHERE id=?")->execute([$id]);$event='approved';}}$pdo->commit();if(in_array($event,['approved','rejected'],true)&&$r['alimtalk_opt_in'])send_alimtalk($event,'employee',$r['employee_id'],$r['phone'],['var1'=>trim($r['employee_name'].' '.$r['position']),'var2'=>$r['start_date'],'var3'=>$r['end_date'],'var4'=>fmt_days($r['requested_days']),'var5'=>$comment]);elseif($event==='next_approval'&&!empty($nextApproval)){$q=$pdo->prepare('SELECT name,phone,alimtalk_opt_in FROM employees WHERE id=?');$q->execute([$nextApproval['approver_employee_id']]);$na=$q->fetch();if($na&&$na['alimtalk_opt_in'])send_alimtalk('next_approval','employee',$nextApproval['approver_employee_id'],$na['phone'],['var1'=>trim($r['employee_name'].' '.$r['position']),'var2'=>$r['start_date'],'var3'=>$r['end_date'],'var4'=>fmt_days($r['requested_days']),'var5'=>$na['name']]);}$msg='처리되었습니다.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();}}
[$scopeSql,$scopeParams]=request_scope_sql('e');$status=trim($_GET['status']??'');$where=[$scopeSql];$params=$scopeParams;if($status!==''){$where[]='lr.status=?';$params[]=$status;}if(!can_manage_hr()&&admin_employee_id()){$where[]='(e.department_id IN ('.implode(',',array_fill(0,count(accessible_department_ids()),'?')).') OR EXISTS(SELECT 1 FROM request_approvals mine WHERE mine.request_id=lr.id AND mine.approver_employee_id=?))';$params=[...$scopeParams,...accessible_department_ids(),admin_employee_id()];}$sql="SELECT lr.*,e.name employee_name,e.position,d.name department_name,lt.name leave_name,GROUP_CONCAT(CONCAT(ra.step_order,':',ae.name,'(',ra.status,')') ORDER BY ra.step_order SEPARATOR ' / ') approval_state,MAX(CASE WHEN ra.approver_employee_id=? AND ra.status='pending' THEN 1 ELSE 0 END) my_turn FROM leave_requests lr JOIN employees e ON e.id=lr.employee_id LEFT JOIN departments d ON d.id=e.department_id JOIN leave_types lt ON lt.id=lr.leave_type_id LEFT JOIN request_approvals ra ON ra.request_id=lr.id LEFT JOIN employees ae ON ae.id=ra.approver_employee_id WHERE ".implode(' AND ',$where)." GROUP BY lr.id ORDER BY lr.id DESC LIMIT 300";$params=[admin_employee_id(),...$params];$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
?><div class="page-title-row"><div><h1>신청·결재 관리</h1><p class="page-desc">결재권자는 담당 부서 및 자신에게 배정된 신청만 조회·처리합니다.</p></div></div><?php if($msg):?><div class="alert ok"><?=h($msg)?></div><?php endif?><?php if($err):?><div class="alert err"><?=h($err)?></div><?php endif?><form class="filter-bar" method="get"><label>상태<select name="status"><option value="">전체</option><?php foreach(['in_approval'=>'결재중','approved'=>'승인','rejected'=>'반려','cancelled'=>'취소'] as $k=>$v):?><option value="<?=$k?>" <?=$status===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><button class="btn">조회</button></form><div class="card"><div class="table-wrap"><table class="table"><tr><th>신청자</th><th>부서</th><th>유형/기간</th><th>일수</th><th>상태/결재선</th><th>처리</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['employee_name'].' '.$r['position'])?></td><td><?=h($r['department_name']?:'-')?></td><td><?=h($r['leave_name'])?><div class="muted"><?=h($r['start_date'])?> ~ <?=h($r['end_date'])?></div></td><td><?=fmt_days($r['requested_days'])?></td><td><span class="badge"><?=h($r['status'])?></span><div class="muted"><?=h($r['approval_state'])?></div></td><td><?php if(in_array($r['status'],['pending','in_approval'])&&($r['my_turn']||can_manage_hr())):?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input name="comment" placeholder="의견/반려사유"><div class="actions"><button class="btn sm" name="action" value="approve">승인</button><button class="btn sm red" name="action" value="reject">반려</button></div></form><?php else:?><span class="muted">처리 권한 없음</span><?php endif?></td></tr><?php endforeach?></table></div></div><?php include '_bottom.php';?>